def clean(df):
    df = df.copy()
    region_map = {
        'north': 'North',
        'Nort': 'North',
        'east': 'East',
        'Suoth': 'South',
        'Wst': 'West'
    }
    df['Region'] = df['Region'].replace(region_map)
    return df

def answer(df):
    result = df.groupby('Region')['Quantity'].sum()
    return {k: int(v) for k, v in result.items()}
